 22→// fileChange represents a single file addition, update, or deletion.
 23→type fileChange struct {
 24→	hash   plumbing.Hash
 25→	mode   filemode.FileMode
 26→	delete bool
 27→}
 28→
 29→func newChangeTree() *changeTree {
 30→	return &changeTree{
 31→		dirs:  make(map[string]*changeTree),
 32→		files: make(map[string]*fileChange),
 33→	}
 34→}
