 36→// addFile records a file addition or update in the change tree.
 37→// The path uses forward slashes as separators (git convention).
 38→func (ct *changeTree) addFile(path string, hash plumbing.Hash, mode filemode.FileMode) {
 39→	parts := strings.Split(path, "/")
 40→	node := ct
 41→	for _, part := range parts[:len(parts)-1] {
 42→		if _, ok := node.dirs[part]; !ok {
 43→			node.dirs[part] = newChangeTree()
 44→		}
 45→		node = node.dirs[part]
 46→	}
 47→	node.files[parts[len(parts)-1]] = &fileChange{hash: hash, mode: mode}
 48→}
