 68→// applyChangesToTree merges a changeTree into a base git tree, returning the new root tree hash.
 69→// Only directories containing changes are rebuilt; unchanged subtrees are reused by hash reference.
 70→// This is O(changed_files * tree_depth) instead of O(total_files_in_repo).
 71→func applyChangesToTree(repo *git.Repository, baseTreeHash plumbing.Hash, changes *changeTree) (plumbing.Hash, error) {
 72→	if changes.isEmpty() {
 73→		return baseTreeHash, nil
 74→	}
 75→
 76→	baseTree, err := repo.TreeObject(baseTreeHash)
 77→	if err != nil {
 78→		return plumbing.ZeroHash, fmt.Errorf("failed to get tree: %w", err)
 79→	}
 80→
 81→	// Track which change entries we've processed (matched to existing tree entries)
 82→	processedDirs := make(map[string]bool)
 83→	processedFiles := make(map[string]bool)
 84→
 85→	var newEntries []object.TreeEntry
 86→
 87→	// Process existing entries
 88→	for _, entry := range baseTree.Entries {
 89→		if entry.Mode == filemode.Dir {
 90→			if dirChanges, ok := changes.dirs[entry.Name]; ok {
 91→				// Recurse into subdirectory with changes
 92→				newSubHash, subErr := applyChangesToTree(repo, entry.Hash, dirChanges)
 93→				if subErr != nil {
 94→					return plumbing.ZeroHash, subErr
 95→				}
 96→				newEntries = append(newEntries, object.TreeEntry{
 97→					Name: entry.Name,
 98→					Mode: filemode.Dir,
 99→					Hash: newSubHash,
100→				})
101→				processedDirs[entry.Name] = true
102→			} else {
103→				// No changes in this directory, keep as-is
104→				newEntries = append(newEntries, entry)
105→			}
106→		} else {
107→			// File entry
108→			if change, ok := changes.files[entry.Name]; ok {
109→				if !change.delete {
110→					newEntries = append(newEntries, object.TreeEntry{
111→						Name: entry.Name,
112→						Mode: change.mode,
113→						Hash: change.hash,
114→					})
115→				}
116→				// If delete: don't add to newEntries
117→				processedFiles[entry.Name] = true
118→			} else {
119→				// No change, keep as-is
120→				newEntries = append(newEntries, entry)
121→			}
122→		}
123→	}
124→
125→	// Add new files (not in base tree)
126→	for name, change := range changes.files {
127→		if !processedFiles[name] && !change.delete {
128→			newEntries = append(newEntries, object.TreeEntry{
129→				Name: name,
130→				Mode: change.mode,
131→				Hash: change.hash,
132→			})
133→		}
134→	}
135→
136→	// Add new directories (not in base tree)
137→	for name, dirChanges := range changes.dirs {
138→		if !processedDirs[name] {
139→			newSubHash, subErr := createTreeFromChanges(repo, dirChanges)
140→			if subErr != nil {
141→				return plumbing.ZeroHash, subErr
142→			}
143→			newEntries = append(newEntries, object.TreeEntry{
144→				Name: name,
145→				Mode: filemode.Dir,
146→				Hash: newSubHash,
147→			})
148→		}
149→	}
150→
151→	sortTreeEntries(newEntries)
152→	return storeTree(repo, newEntries)
153→}
