155→// createTreeFromChanges creates a new tree from a changeTree with no base tree.
156→// Used for new directories that don't exist in the base tree.
157→func createTreeFromChanges(repo *git.Repository, changes *changeTree) (plumbing.Hash, error) {
158→	var entries []object.TreeEntry
159→
160→	for name, change := range changes.files {
161→		if !change.delete {
162→			entries = append(entries, object.TreeEntry{
163→				Name: name,
164→				Mode: change.mode,
165→				Hash: change.hash,
166→			})
167→		}
168→	}
169→
170→	for name, dirChanges := range changes.dirs {
171→		subHash, err := createTreeFromChanges(repo, dirChanges)
172→		if err != nil {
173→			return plumbing.ZeroHash, err
174→		}
175→		entries = append(entries, object.TreeEntry{
176→			Name: name,
177→			Mode: filemode.Dir,
178→			Hash: subHash,
179→		})
180→	}
181→
182→	sortTreeEntries(entries)
183→	return storeTree(repo, entries)
184→}
