186→// storeTree creates and stores a git tree object from entries.
187→func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
188→	tree := &object.Tree{Entries: entries}
189→	obj := repo.Storer.NewEncodedObject()
190→	if err := tree.Encode(obj); err != nil {
191→		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
192→	}
193→	hash, err := repo.Storer.SetEncodedObject(obj)
194→	if err != nil {
195→		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
196→	}
197→	return hash, nil
198→}
