200→// addDirectoryToChangeTree walks a filesystem directory and adds all files to a changeTree.
201→// dirPathAbs is the absolute path for reading files, dirPathRel is the git tree path prefix.
202→func addDirectoryToChangeTree(repo *git.Repository, dirPathAbs, dirPathRel string, ct *changeTree) error {
203→	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, walkErr error) error {
204→		if walkErr != nil {
205→			return walkErr
206→		}
207→		if info.IsDir() {
208→			return nil
209→		}
210→
211→		relWithinDir, relErr := filepath.Rel(dirPathAbs, path)
212→		if relErr != nil {
213→			return fmt.Errorf("failed to get relative path for %s: %w", path, relErr)
214→		}
215→
216→		blobHash, mode, blobErr := createBlobFromFile(repo, path)
217→		if blobErr != nil {
218→			return fmt.Errorf("failed to create blob for %s: %w", path, blobErr)
219→		}
220→
221→		// Use forward slashes for git tree paths
222→		treePath := dirPathRel + "/" + filepath.ToSlash(relWithinDir)
223→		ct.addFile(treePath, blobHash, mode)
224→		return nil
225→	})
226→	if err != nil {
227→		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
228→	}
229→	return nil
230→}
